// swift-tools-version: 5.10
// A small Kiln reader: generated models, a sync mirror and two SwiftUI
// screens. `swift test` runs on macOS; `swift run SwiftUIReader` opens the
// macOS window; `xcodegen` + project.yml builds the same screens for iOS.
import PackageDescription

let package = Package(
    name: "SwiftUIReader",
    platforms: [.iOS(.v17), .macOS(.v14)],
    products: [
        .library(name: "KilnReader", targets: ["KilnReader"]),
        .executable(name: "SwiftUIReader", targets: ["SwiftUIReader"]),
    ],
    targets: [
        // Generated by `bin/regenerate` (`mix kiln.export.schema --format swift`).
        .target(name: "KilnModels"),
        .target(name: "KilnReader", dependencies: ["KilnModels"]),
        .executableTarget(name: "SwiftUIReader", dependencies: ["KilnReader"]),
        .testTarget(
            name: "KilnReaderTests",
            dependencies: ["KilnReader", "KilnModels"],
            resources: [.copy("Fixtures")]
        ),
    ]
)
